mapper.select:
SELECT id, title, category, summary, content, author, view_count AS viewCount, status, create_time AS createTime FROM psy_knowledge WHERE status = 1
AND category = #{category}
ORDER BY create_time DESC

mapper.update:
UPDATE psy_knowledge
SET title    = #{title},
    category = #{category},
    summary  = #{summary},
    content  = #{content}
WHERE id = #{id}

UPDATE psy_test_record
SET doctor_conclusion = #{conclusion},
    doctor_advice     = #{advice}
WHERE record_id = #{recordId}
